<!doctype html><html lang="id" class="bg-[#0d0f11]"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Ruang kendali · Sandbox</title><script src="https://cdn.tailwindcss.com?plugins=forms"></script><script>tailwind.config={theme:{extend:{fontFamily:{display:['Fraunces','Georgia','serif'],sans:['Geist','sans-serif'],mono:['JetBrains Mono','monospace']},colors:{line:'#2a323b',surface:'#171b21',accent:'#dab383'}}}}</script><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,300..900&family=Geist:wght@400;500;600;700&family=JetBrains+Mono&display=swap" rel="stylesheet"><style>[v-cloak]{display:none}body{font-family:Geist,sans-serif;background:radial-gradient(circle at 10% -10%,#2b2520,transparent 31%),#0d0f11;color:#f2ece0}.active{background:#dab383;color:#17110d;border-color:#dab383}</style></head>
<body><div id="app" v-cloak class="min-h-screen"><header class="sticky top-0 z-20 border-b border-line bg-[#0d0f11]/90 backdrop-blur"><div class="mx-auto flex max-w-7xl items-center justify-between px-5 py-4"><a href="{{ route('catalog.index') }}" class="font-display text-xl">Arsip Layar <small class="font-mono text-[10px] uppercase text-accent">sandbox</small></a><form method="post" action="{{ route('logout') }}">@csrf<button class="rounded-lg border border-line px-3 py-2 text-sm">Keluar</button></form></div></header>
<main class="mx-auto grid max-w-7xl gap-8 px-5 py-8 lg:grid-cols-[220px_minmax(0,1fr)]"><aside class="lg:sticky lg:top-24 lg:h-fit"><p class="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Control panel</p><h1 class="mt-2 font-display text-4xl">Ruang<br>kendali.</h1><p class="mt-4 text-sm leading-6 text-zinc-400">Laravel terisolasi. Tidak memakai rahasia atau media produksi.</p><nav class="mt-7 flex gap-2 overflow-x-auto pb-2 lg:flex-col"><button v-for="item in tabs" @click="tab=item[0]" :class="tab===item[0]?'active':'border-line text-zinc-300'" class="whitespace-nowrap rounded-lg border px-3 py-2 text-left text-sm">[[item[1]]]</button></nav></aside>
<section><div class="mb-7 flex items-end justify-between"><div><p class="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Penerbitan · {{ now()->translatedFormat('d M Y') }}</p><h2 class="mt-2 font-display text-5xl">[[title]]</h2></div><span class="rounded-full border border-emerald-800 bg-emerald-950/50 px-3 py-1 text-xs text-emerald-200">● Sandbox aktif</span></div><p v-if="notice" class="mb-5 rounded-xl border border-emerald-800 bg-emerald-950/50 p-3 text-sm text-emerald-100">[[notice]]</p><p v-if="error" class="mb-5 rounded-xl border border-rose-800 bg-rose-950/50 p-3 text-sm text-rose-100">[[error]]</p>

<div v-show="tab==='content'" class="space-y-5"><div class="grid gap-5 md:grid-cols-2"><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Perpustakaan</p><h3 class="mt-2 font-display text-3xl">Konten sandbox</h3><div class="mt-5 grid grid-cols-2 gap-3"><div class="rounded-xl bg-black/20 p-4"><strong class="text-3xl">[[overview.metrics?.videos||0]]</strong><small class="block text-zinc-400">video</small></div><div class="rounded-xl bg-black/20 p-4"><strong class="text-3xl">[[overview.metrics?.ready||0]]</strong><small class="block text-zinc-400">siap</small></div></div></article><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Kategori</p><h3 class="mt-2 font-display text-3xl">Koleksi</h3><form class="mt-5 flex gap-2" method="post" action="{{route('admin.categories.store')}}">@csrf<input name="name" required placeholder="Nama kategori" class="min-w-0 flex-1 rounded-lg border-line bg-black/20 text-sm"><button class="rounded-lg bg-accent px-4 text-sm font-semibold text-[#17110d]">Tambah</button></form><div class="mt-5 flex flex-wrap gap-2">@foreach($categories as $c)<span class="rounded-full border border-line px-3 py-1 text-xs">{{$c->name}} · {{$c->videos_count}}</span>@endforeach</div></article></div><article class="overflow-hidden rounded-2xl border border-line bg-surface"><div class="border-b border-line p-5 font-display text-2xl">Video terbaru</div><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-left text-sm"><thead class="font-mono text-[10px] uppercase text-zinc-500"><tr><th class="p-4">Judul</th><th>Kategori</th><th>Durasi</th><th>Views</th><th>Status</th></tr></thead><tbody>@foreach($videos as $v)<tr class="border-t border-line/70"><td class="p-4 font-medium">{{$v->title}}</td><td>{{$v->category?->name??'—'}}</td><td>{{gmdate('i:s',$v->duration_seconds)}}</td><td>{{$v->views}}</td><td><span class="rounded-full bg-emerald-950 px-2 py-1 text-xs text-emerald-200">{{$v->status}}</span></td></tr>@endforeach</tbody></table></div></article></div>

<div v-show="tab==='analytics'" class="space-y-5"><div class="flex gap-2"><button v-for="d in [7,30,90]" @click="analyticsLoad(d)" class="rounded-lg border border-line px-3 py-2 text-xs">[[d]] hari</button></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="m in cards" class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-zinc-500">[[m[0]]]</p><strong class="mt-2 block font-display text-4xl">[[m[1]]]</strong></div></div><article class="rounded-2xl border border-line bg-surface p-5"><h3 class="font-display text-2xl">Halaman populer</h3><div v-if="analytics.popular?.length" class="mt-4 space-y-3"><div v-for="r in analytics.popular" class="flex justify-between border-b border-line pb-3 text-sm"><span>[[r.path]]</span><strong>[[r.views]]</strong></div></div><p v-else class="mt-4 text-sm text-zinc-500">Belum ada event analytics sandbox.</p></article></div>

<div v-show="tab==='security'" class="grid gap-5 lg:grid-cols-2"><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Keamanan</p><h3 class="mt-2 font-display text-3xl">Admin sandbox</h3><dl class="mt-5 space-y-3 text-sm"><div class="flex justify-between border-b border-line pb-3"><dt class="text-zinc-500">Email</dt><dd>{{auth()->user()->email}}</dd></div><div class="flex justify-between"><dt class="text-zinc-500">Login terakhir</dt><dd>{{auth()->user()->last_login_at?->format('d M H:i')??'—'}}</dd></div></dl></article><article class="rounded-2xl border border-line bg-surface p-5"><h3 class="font-display text-3xl">Lapisan aktif</h3><ul class="mt-5 space-y-3 text-sm text-zinc-300"><li>✓ CSRF Laravel</li><li>✓ Session database + rotasi login</li><li>✓ Middleware admin</li><li>✓ Hash SHA-256 untuk token</li><li>✓ Storage media privat sandbox</li></ul></article></div>

<div v-show="tab==='account'" class="rounded-2xl border border-line bg-surface p-6"><p class="font-mono text-[10px] uppercase text-accent">Akun</p><h3 class="mt-2 font-display text-3xl">Profil administrator</h3><p class="mt-4 max-w-xl text-sm leading-6 text-zinc-400">Akun dibuat melalui CLI khusus sandbox agar password produksi tidak pernah berpindah ke lingkungan ini.</p></div>

<div v-show="tab==='system'" class="grid gap-5 lg:grid-cols-2"><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Identitas</p><h3 class="mt-2 font-display text-3xl">Tampilan situs</h3><form @submit.prevent="save" class="mt-5 space-y-3"><input v-model="settings.site_name" placeholder="Nama situs" class="w-full rounded-lg border-line bg-black/20 text-sm"><textarea v-model="settings.site_description" rows="3" class="w-full rounded-lg border-line bg-black/20 text-sm"></textarea><div class="grid grid-cols-2 gap-3"><input v-model="settings.accent" type="color" class="h-10 w-full rounded-lg border-line bg-black/20 p-1"><select v-model="settings.theme_key" class="rounded-lg border-line bg-black/20 text-sm"><option>obsidian</option><option>ivory</option><option>emerald</option></select></div><button class="rounded-lg bg-accent px-4 py-2 text-sm font-semibold text-[#17110d]">Simpan</button></form></article><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Watermark</p><h3 class="mt-2 font-display text-3xl">Konfigurasi konten</h3><form @submit.prevent="save" class="mt-5 space-y-3"><input v-model="settings.watermark_text" placeholder="Teks watermark" class="w-full rounded-lg border-line bg-black/20 text-sm"><select v-model="settings.watermark_position" class="w-full rounded-lg border-line bg-black/20 text-sm"><option value="tl">Kiri atas</option><option value="tr">Kanan atas</option><option value="bl">Kiri bawah</option><option value="br">Kanan bawah</option><option value="center">Tengah</option></select><label class="text-sm">Opasitas [[settings.watermark_opacity]]%<input v-model.number="settings.watermark_opacity" type="range" min="10" max="100" class="mt-2 w-full"></label><label class="flex gap-3 text-sm"><input v-model="settings.maintenance_mode" type="checkbox">Mode perawatan</label><button class="rounded-lg border border-line px-4 py-2 text-sm">Simpan konfigurasi</button></form></article></div>

<div v-show="tab==='tokens'" class="grid gap-5 xl:grid-cols-[1fr_340px]"><article class="overflow-hidden rounded-2xl border border-line bg-surface"><div class="flex items-center justify-between border-b border-line p-5"><h3 class="font-display text-2xl">Token akses</h3><button @click="tokensLoad" class="rounded border border-line px-3 py-2 text-xs">Refresh</button></div><p v-if="plain" class="m-5 rounded-xl border border-emerald-800 bg-emerald-950/50 p-3 text-sm">Simpan token baru: <code>[[plain]]</code></p><div class="overflow-x-auto"><table class="w-full min-w-[600px] text-left text-sm"><thead class="font-mono text-[10px] uppercase text-zinc-500"><tr><th class="p-4">Penerima</th><th>Kontak</th><th>Status</th><th>Pakai</th><th></th></tr></thead><tbody><tr v-for="t in tokens" class="border-t border-line/70"><td class="p-4 font-medium">[[t.label]]</td><td>[[t.contact_type]] · [[t.contact_value]]</td><td>[[t.status]]</td><td>[[t.use_count]]×</td><td><button @click="toggle(t)" class="mr-2 rounded border border-line px-2 py-1 text-xs">Toggle</button><button @click="del(t)" class="rounded border border-rose-900 px-2 py-1 text-xs text-rose-300">Hapus</button></td></tr></tbody></table></div></article><article class="rounded-2xl border border-line bg-surface p-5"><p class="font-mono text-[10px] uppercase text-accent">Terbitkan</p><h3 class="mt-2 font-display text-3xl">Token baru</h3><form @submit.prevent="create" class="mt-5 space-y-3"><input v-model="form.label" required placeholder="Nama penerima" class="w-full rounded-lg border-line bg-black/20 text-sm"><select v-model="form.contact_type" class="w-full rounded-lg border-line bg-black/20 text-sm"><option>telegram</option><option>whatsapp</option><option>facebook</option></select><input v-model="form.contact_value" required placeholder="Kontak" class="w-full rounded-lg border-line bg-black/20 text-sm"><button class="w-full rounded-lg bg-accent py-2 text-sm font-semibold text-[#17110d]">Buat token</button></form></article></div>
<div v-show="tab==='payments'" class="rounded-2xl border border-line bg-surface p-6"><p class="font-mono text-[10px] uppercase text-accent">Midtrans</p><h3 class="mt-2 font-display text-3xl">Belum dikonfigurasi</h3><p class="mt-4 max-w-2xl text-sm leading-6 text-zinc-400">Kunci pembayaran produksi tidak diimpor. Konfigurasikan kredensial Sandbox Midtrans dan webhook idempoten terpisah sebelum checkout diaktifkan.</p></div>
</section></main></div><script src="https://unpkg.com/vue@3/dist/vue.global.prod.js"></script><script>const{createApp,ref,reactive,computed,onMounted}=Vue;createApp({delimiters:['[[',']]'],setup(){const tab=ref('content'),notice=ref(''),error=ref(''),plain=ref(''),tabs=[['content','Konten'],['analytics','Analytics'],['security','Keamanan'],['account','Akun'],['system','Sistem'],['tokens','Akses Token'],['payments','Pembayaran']],overview=reactive({metrics:{}}),analytics=reactive({metrics:{},popular:[]}),tokens=ref([]),settings=reactive({watermark_opacity:60,maintenance_mode:false}),form=reactive({label:'',contact_type:'telegram',contact_value:''}),csrf=document.querySelector('meta[name=csrf-token]').content,req=async(u,o={})=>{const r=await fetch(u,{credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'Content-Type':'application/json'},...o});if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.message||'Permintaan gagal')}return r.status===204?null:r.json()},title=computed(()=>tabs.find(x=>x[0]===tab.value)?.[1]),cards=computed(()=>[['Pengunjung',analytics.metrics.visitors||0],['Page views',analytics.metrics.page_views||0],['Video mulai',analytics.metrics.video_views||0],['Total event',analytics.metrics.total||0]]),flash=x=>{notice.value=x;setTimeout(()=>notice.value='',3500)},load=async()=>{let d=await req('{{route('admin.api.overview')}}');Object.assign(overview,d);Object.assign(settings,d.settings);settings.watermark_opacity=+settings.watermark_opacity;settings.maintenance_mode=settings.maintenance_mode==='1'},analyticsLoad=async(d=30)=>Object.assign(analytics,await req('{{route('admin.api.analytics')}}?days='+d)),tokensLoad=async()=>tokens.value=(await req('{{route('admin.api.tokens')}}')).tokens,save=async()=>{try{await req('{{route('admin.api.settings.update')}}',{method:'PATCH',body:JSON.stringify(settings)});flash('Konfigurasi disimpan.')}catch(e){error.value=e.message}},create=async()=>{try{let d=await req('{{route('admin.api.tokens.create')}}',{method:'POST',body:JSON.stringify(form)});tokens.value.unshift(d.token);plain.value=d.plain_token;Object.assign(form,{label:'',contact_type:'telegram',contact_value:''});flash('Token diterbitkan.')}catch(e){error.value=e.message}},toggle=async t=>{try{Object.assign(t,(await req('{{url('/admin/api/tokens')}}/'+t.id+'/toggle',{method:'PATCH'})).token)}catch(e){error.value=e.message}},del=async t=>{if(!confirm('Hapus token?'))return;try{await req('{{url('/admin/api/tokens')}}/'+t.id,{method:'DELETE'});tokens.value=tokens.value.filter(x=>x.id!==t.id)}catch(e){error.value=e.message}};onMounted(async()=>{try{await Promise.all([load(),analyticsLoad(),tokensLoad()])}catch(e){error.value=e.message}});return{tab,tabs,title,notice,error,overview,analytics,cards,settings,tokens,form,plain,analyticsLoad,tokensLoad,save,create,toggle,del}}).mount('#app')</script></body></html>
